        self.text = text

    def raise_for_status(self):
        if self.status_code >= 400:
            raise Exception(f"HTTP {self.status_code}")


def test_b2c_real_world_usage():
    """Test the actual usage pattern described in the issue."""
    print("=== Testing Real-world B2C Usage Pattern ===")

    authority_url = "https://mytenant.b2clogin.com/mytenant.onmicrosoft.com/B2C_1_signupsignin"
    client_id = "test-client-id-12345"

    app = PublicClientApplication(
        client_id=client_id, 
        authority=authority_url,
        http_client=MockHttpClient()
    )

    print(f"B2C detected: {app.authority._is_b2c}")

    # Test Case 1: What the user wants according to the documentation
    print("\n--- Test Case 1: ['openid', 'offline_access', '<CLIENT_ID>'] ---")
    try:
        # This should work for B2C according to documentation
        scopes = ['openid', 'offline_access', client_id]
        result = app._decorate_scope(scopes)
        print(f"Result: {result}")
        expected_elements = ['openid', 'offline_access', 'profile', client_id]
        if all(elem in result for elem in expected_elements):
            print("✓ Works correctly - all expected elements present")
        else:
            print(f"? Missing elements. Expected to contain {expected_elements}")
    except Exception as e:
        print(f"✗ Failed: {e}")

    # Test Case 2: Just client ID (the current problematic case)
    print("\n--- Test Case 2: ['<CLIENT_ID>'] ---")
    try:
        result = app._decorate_scope([client_id])
        print(f"Result: {result}")
        if client_id in result and 'openid' in result and 'profile' in result and 'offline_access' in result:
            print("✓ Works correctly - client ID preserved with reserved scopes")
        else:
            print("? Unexpected result")
    except Exception as e:
        print(f"✗ Failed: {e}")

    # Test Case 3: Regular non-B2C should still work the same
    print("\n--- Test Case 3: Regular authority behavior ---")
    regular_app = PublicClientApplication(client_id=client_id, authority="https://login.microsoftonline.com/common")

    try:
        result = regular_app._decorate_scope([client_id])
        print(f"Regular result: {result}")
        if set(result) == {'openid', 'profile', 'offline_access'}:
            print("✓ Regular behavior unchanged")
        else:
            print("? Regular behavior changed unexpectedly")
    except Exception as e:
        print(f"Regular failed: {e}")

    try:
        # This should still fail for regular apps
        result = regular_app._decorate_scope([client_id, 'openid'])
        print(f"Regular mixed result: {result}")
        print("? This should have failed")
    except ValueError as e:
        print(f"✓ Regular still correctly rejects mixed scopes: {e}")
    except Exception as e:
        print(f"Regular mixed failed with unexpected error: {e}")


if __name__ == "__main__":
    test_b2c_real_world_usage()

